#!/usr/bin/env python
# -*- coding: utf-8 -*-
"""Synthetic demo data, generated by ``sklearn.datasets.make_classification``.

    python3 -m tabpfn_anchor.demo.sklearn_toy --preset wide -o wide.tsv

**Nothing here reads or approximates any cohort.** The generator is a single
call into scikit-learn with the arguments below; there is no constant taken
from a real gene, subtype or cohort, and no summary statistic of one. That is
what makes the following claim checkable rather than merely asserted:

    The demo data contain no patient observations, no gene identifiers, and no
    statistic derived from any biological cohort. They reproduce the shape of
    the task -- far more features than samples, a handful of informative
    features, many correlated near-duplicates of them, and imbalanced classes
    -- and nothing else.

In particular the values are not on an expression scale and the columns are
named ``feature_00001``, not after genes. Anything read into these numbers
beyond ``p >> n`` is read in by the reader.

Two presets:

    quick   300 x 1,000    installation and API check
    wide    500 x 10,000   p >> n, enough features for K = 9 views of 500

``n_informative`` features carry the class signal and ``n_redundant`` more are
random linear combinations of them. Neither number is the anchor budget: the
method selects 100 anchors whatever the data contain, and matching the two
would make the demo look rigged. That pairing is what makes the data worth
running a staged selector on: a marginal screen cannot tell an informative
feature from its correlated copies, so there is something for the later stages
to reorder.

The seed is fixed, so the same call gives the same table.
"""

from __future__ import annotations

import argparse

import numpy as np
import pandas as pd

#: Preset shapes. ``wide`` is sized so that the published view construction
#: (100 anchors + 9 disjoint blocks of 400 = 3,700 distinct features) fits.
#:
#: ``class_sep`` is set per preset so that the task is worth running. Too high
#: and every method scores near 1.0, which says nothing about whether the code
#: works; too low and nothing is learnable. At these values five-fold macro-F1
#: for ordinary baselines lands at
#:
#:     quick   logistic regression 0.78   random forest 0.86
#:     wide    logistic regression 0.83   random forest 0.83
#:
#: Neither baseline dominates, so the staged selection has something to do.
#: Re-measure these if the parameters change; a saturated demo hides faults.
PRESETS = {
    "quick": dict(n_samples=300, n_features=1_000,
                  n_informative=20, n_redundant=80, class_sep=2.5),
    "wide": dict(n_samples=500, n_features=10_000,
                 n_informative=50, n_redundant=450, class_sep=3.0),
}

DEFAULT_SEED = 20260902

#: Deliberately imbalanced, like a subtype distribution. macro-F1 is the
#: endpoint precisely because it does not let the largest class carry the
#: score. The smallest class still has to be large enough to survive a
#: stratified split and the inner stacking folds.
CLASS_WEIGHTS = (0.40, 0.28, 0.20, 0.12)


def make_toy(preset: str = "quick", seed: int = DEFAULT_SEED, **overrides):
    """Return ``(X, y, signal)``.

    ``X`` is a DataFrame of ``feature_%05d`` columns, ``y`` a Series of
    ``Class_A``..``Class_D``, and ``signal`` records which column names the
    generator made informative or redundant -- a key that real data does not
    come with, and which the example script uses to show the anchors are not
    arbitrary.
    """
    from sklearn.datasets import make_classification

    if preset not in PRESETS:
        raise ValueError(f"preset must be one of {sorted(PRESETS)}: {preset!r}")
    cfg = dict(PRESETS[preset], **overrides)
    n_features = cfg["n_features"]
    n_informative = cfg["n_informative"]
    n_redundant = cfg["n_redundant"]

    # shuffle=False keeps the informative block first, the redundant block
    # second and pure noise after them, so the positions are known. The columns
    # are then permuted here with a seed we hold, which both hides the layout
    # from the selector and leaves the key recoverable.
    X, y_int = make_classification(
        n_samples=cfg["n_samples"],
        n_features=n_features,
        n_informative=n_informative,
        n_redundant=n_redundant,
        n_repeated=0,
        n_classes=len(CLASS_WEIGHTS),
        n_clusters_per_class=2,
        weights=list(CLASS_WEIGHTS),
        class_sep=cfg["class_sep"],
        flip_y=0.01,
        shuffle=False,
        random_state=seed,
    )

    rng = np.random.default_rng(seed)
    col_order = rng.permutation(n_features)
    row_order = rng.permutation(len(y_int))

    names = np.array([f"feature_{j + 1:05d}" for j in range(n_features)])
    names = names[col_order]

    Xdf = pd.DataFrame(np.round(X[np.ix_(row_order, col_order)], 6), columns=names)
    y = pd.Series([f"Class_{chr(65 + c)}" for c in y_int[row_order]], name="subtype")

    # position -> new column index, so the planted blocks can be named back
    where = np.empty(n_features, dtype=int)
    where[col_order] = np.arange(n_features)
    signal = {
        "informative": sorted(names[where[j]] for j in range(n_informative)),
        "redundant": sorted(names[where[j]]
                            for j in range(n_informative, n_informative + n_redundant)),
    }
    return Xdf, y, signal


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--preset", choices=sorted(PRESETS), default="quick")
    ap.add_argument("-o", "--out", default=None,
                    help="write a TSV; omit to only print the shape")
    ap.add_argument("--seed", type=int, default=DEFAULT_SEED)
    a = ap.parse_args()

    X, y, signal = make_toy(a.preset, seed=a.seed)
    print(f"[*] preset={a.preset}  {X.shape[0]} samples x {X.shape[1]:,} features  "
          f"seed={a.seed}")
    print("[*] " + "  ".join(f"{k}={v}" for k, v in
                             y.value_counts().sort_index().items()))
    print(f"[*] planted: {len(signal['informative'])} informative, "
          f"{len(signal['redundant'])} redundant")
    if a.out:
        out = X.copy()
        out.insert(0, "subtype", y.to_numpy())
        out.to_csv(a.out, sep="\t", index=False)
        print(f"[*] {a.out}")


if __name__ == "__main__":
    main()
